let difRecentScenes=[],ombresLastTargetId=null,ombresAutoTimer=null,difLastSig='',difLastSceneId='',difAutoTimer=null,difPreloadTimer=null,difPreloadToken=0;
const DIF_PRELOAD_MS=15000;
function difClearPreload(){if(difPreloadTimer){clearTimeout(difPreloadTimer);difPreloadTimer=null}difPreloadToken++}
function difNeedsStartBtn(){const d=jocs.diferencies;return d.missionIndex===0&&d.stars===0}
function difRoundUrls(){const sc=difScene(),urls=[],pend=jocs.diferencies.pendingRound,act=pend?.active||jocs.diferencies.active,dec=pend?.decoys||jocs.diferencies.decoys||[];if(sc?.base)urls.push(strip(sc.base));act.forEach(p=>{if(p?.img)urls.push(strip(p.img))});dec.forEach(p=>{if(p?.img)urls.push(strip(p.img))});return[...new Set(urls.filter(Boolean))]}
function difOnPreloadComplete(){const d=jocs.diferencies;d.assetsReady=true;const pending=d.pendingRound;if(pending){d.active=pending.active;d.decoys=pending.decoys;d.pendingRound=null;d.found=new Set()}const ph=d.phase;if(ph==='ready'){if(state.place==='jocsDiferencies')render();return}if(ph==='sceneDone'||ph==='found')d.phase='searching';else if(difNeedsStartBtn())d.phase='ready';else d.phase='searching';if(state.place==='jocsDiferencies')render()}
function difPreloadRound(){jocs.diferencies.assetsReady=false;const token=++difPreloadToken;if(difPreloadTimer){clearTimeout(difPreloadTimer);difPreloadTimer=null}const urls=difRoundUrls(),finish=()=>{if(token!==difPreloadToken)return;difPreloadTimer=null;difOnPreloadComplete()};if(!urls.length){finish();return}if(typeof Image==='undefined'){finish();return}let left=urls.length;const step=()=>{if(--left<=0)finish()};difPreloadTimer=setTimeout(finish,DIF_PRELOAD_MS);urls.forEach(src=>{const im=new Image();im.onload=im.onerror=step;im.src=src})}
const OMBRES_NOPE_MS=400;
const OMBRES_WRONG_MSG_MS=1500;
function difClearAuto(){if(difAutoTimer){clearTimeout(difAutoTimer);difAutoTimer=null}difClearPreload()}
function difRoundsGoalEffective(){const ctx=jocs.diferencies?.context;return ctx?.mode==='missio'&&ctx.roundsGoal!=null?Math.max(1,Math.min(3,Math.floor(ctx.roundsGoal))):difRoundsGoal()}
function difSessionIdNew(){return typeof activitatsSessionId==='function'?activitatsSessionId():`s${Date.now().toString(36)}${Math.random().toString(36).slice(2,10)}`}
function difActivitatsRuntimeOn(){return typeof activitatsReg!=='undefined'&&activitatsReg.ready&&!activitatsReg.failed}
function difContextLliure(){return {mode:'lliure',forcedSceneId:null,roundsGoal:null,returnPlace:null}}
