function ombresBriefingHtml(){const m=ombresMissions(),where=strip(m.briefingRoom||m.subtitle||'LA TORRE');return `<div class="ombres-pop ombres-pop--briefing" role="dialog" aria-modal="true"><div class="ombres-pop-card ombres-pop-card--briefing"><p class="dif-ready-scene ombres-briefing-room">${where}</p>${ombresSalaTowerImg()}${ombresBuscaBtn(jocs.ombres.targetId,'ombres-begin-search')}</div></div>`}
