function ombresPickLevelHtml(){ombresEnsureSession();const max=f2.ombresSession?.levelUnlocked??0;let btns='';for(let i=0;i<=max;i++)btns+=ombresLevelBtn(`NIVELL ${i+1}`,`ombres-play-level-${i}`,'secondary');const nova=ombresHasProgress()?`<div class="ombres-level-pick-nova">${ombresLevelBtn('NOVA AVENTURA','ombres-nova-aventura','secondary')}</div>`:'';return `<div class="ombres-pop ombres-pop--levels" role="dialog" aria-modal="true"><div class="ombres-pop-card ombres-pop-card--levels"><div class="ombres-level-pick">${btns}</div>${nova}</div></div>`}
