function difGaReturnBtn(){const ctx=jocs.diferencies.context;return ctx?.returnPlace==='granAventura'?ombresLevelBtn('TORNA A L\'AVENTURA','ga-return-hub','primary'):ombresLevelBtn('TORNA A LA TORRE','end-jocs-diferencies','secondary')}
function ombresLevelDoneHtml(){const gm=f2.granMissio;if(gm?.activitatId==='ombres'){const inner=typeof gaMissioVictoryHtml==='function'?gaMissioVictoryHtml('HAS TROBAT TOTES LES OMBRES!'):'';return `<div class="ombres-level-done ombres-level-done--gran-missio">${inner}</div>`}const m=ombresMissions(),tower=strip(m.celebrateTower||'imagenes/torre.webp'),lvl=ombresPlayingLevel(),msg=strip(m.completedMsg||'LA TORRE BRILLA GRÀCIES A TU!');let head,stars,primary,sec='';if(lvl===3){head=`<p id="ombres-nivell-title" class="ombres-pop-title">${'HAS SUPERAT TOTS ELS NIVELLS!'}</p><p class="ombres-level-done-msg">${msg}</p>`;stars=`<div class="ombres-celebrate-stars ombres-celebrate-stars--all-levels" aria-hidden="true">${ombresAllLevelStarsHtml()}</div>`;primary=ombresLevelBtn('NOVA AVENTURA','ombres-nova-aventura','primary');sec=ombresLevelBtn('TORNA A JUGAR','ombres-replay-level','secondary')+ombresLevelBtn('TORNA A LA TORRE','end-jocs-ombres','secondary')}else{head=`<p id="ombres-nivell-title" class="ombres-pop-title">${msg}</p>`;stars=`<div class="ombres-celebrate-stars" aria-hidden="true">${ombresStarsHtml()}</div>`;primary=ombresLevelBtn(`JUGA AL NIVELL ${lvl+2}`,`ombres-play-level-${lvl+1}`,'primary');sec=ombresLevelBtn('TORNA A JUGAR','ombres-replay-level','secondary')+ombresLevelBtn('TORNA A LA TORRE','end-jocs-ombres','secondary')}return `<div class="ombres-level-done" role="region" aria-labelledby="ombres-nivell-title"><img class="ombres-premi-tower" src="${tower}" alt="" draggable="false"><div class="ombres-pop ombres-pop--level-done"><div class="ombres-pop-card ombres-pop-card--level-done">${head}${stars}<div class="ombres-level-btns"><div class="ombres-level-btns-primary">${primary}</div><div class="ombres-level-btns-sec">${sec}</div></div></div></div></div>`}
function ombresCelebrateHtml(){const m=ombresMissions(),tower=strip(m.celebrateTower||'imagenes/torre.webp'),all=ombresAllSecrets(),ids=[...new Set([...jocs.ombres.usedTargets,jocs.ombres.targetId])].filter(Boolean);const cards=ids.map(id=>all.find(s=>s.id===id)).filter(Boolean).map((s,i)=>`<figure class="ombres-premi-card" style="--pi:${i}"><div class="ombres-premi-pic"><img class="ombres-premi-shadow" src="${strip(s.img)}" alt="" draggable="false"><img class="ombres-premi-color" src="${strip(s.color||s.img)}" alt="" draggable="false"></div><figcaption>${strip(s.name||'')}</figcaption></figure>`).join('');return `<div class="ombres-celebrate ombres-celebrate--premi" role="region" aria-labelledby="ombres-celebrate-title"><img class="ombres-premi-tower" src="${tower}" alt="" draggable="false"><div class="ombres-celebrate-stars" aria-hidden="true">${ombresStarsHtml()}</div><p id="ombres-celebrate-title" class="ombres-premi-title">${strip(m.completedTitle||'')}</p><div class="ombres-premi-cards">${cards}</div><p class="ombres-celebrate-msg">${strip(m.completedMsg||'')}</p></div>`}
function ombresFoundPopHtml(){const m=ombresMissions(),all=ombresAllSecrets(),s=all.find(x=>x.id===jocs.ombres.targetId);if(!s)return'';const next=jocs.ombres.nextTargetId?all.find(x=>x.id===jocs.ombres.nextTargetId):null;const follow=next?ombresBuscaBtn(next.id,'ombres-next-mission'):`<div class="ombres-pop-actions">${f2btn(strip(m.finishBtn||'✨ CONTINUA'),'ombres-finish-level')}</div>`;return `<div class="ombres-pop" role="dialog" aria-modal="true" aria-labelledby="ombres-pop-title"><div class="ombres-pop-card"><p id="ombres-pop-title" class="ombres-pop-title">${ombresFoundLabel(s.id)}</p><img class="ombres-pop-img" src="${strip(s.color||s.img)}" alt="" draggable="false">${follow}</div></div>`}
function ombresOnLevelComplete(){jocs.ombres.starPop=false;jocs.ombres.phase='levelDone'}
function ombresAdvanceMission(){jocs.ombres.usedTargets.push(jocs.ombres.targetId);jocs.ombres.missionIndex=Math.min(2,jocs.ombres.missionIndex+1);ombresPrepMission('searching')}
function ensureOmbres(cb){
 if(jocs.ombres.data)return cb();
 if(jocs.ombres.load){jocs.ombres.load.then(cb);return}
 jocs.ombres.load=fetch(OMBRES_URL).then(r=>r.json()).then(d=>{jocs.ombres.data=d;cb()}).catch(()=>{notify('NO PUC CARREGAR LES OMBRES');cb()});
}
function personatgeList(){return jocs.personatges?.personatges||[]}
function personatgePool(){return personatgeList().filter(p=>p.enabled!==false&&strip(p.img))}
function jocsPairMeta(id){return personatgeList().find(p=>p.id===id)||null}
function jocsPairLevels(){const l=jocs.personatges?.nivells;return Array.isArray(l)&&l.length?l:[{id:'base',label:'',parelles:jocs.personatges?.pairsPerRound||5}]}
