Object.assign(SCENES,{jocs:jocsMenuScene,jocsCount:jocsCountScene,jocsPuzle:jocsPuzleScene,jocsPocio:jocsPocioScene,jocsOmbres:jocsOmbresScene,jocsLupa:jocsLupaMenuScene,jocsDiferencies:jocsDiferenciesScene});
const hotspotJocs=hotspot;
hotspot=function(id){if(state.place==='workshop'&&id==='search'){go('jocs');return}if(state.place==='tower'&&id==='lupa'){go('jocsLupa');return}return hotspotJocs(id)};
const actionJocs=action;
action=function(id){switch(id){
case'jocs-search':go('search');return;
case'jocs-count':go('jocsCount');return;
case'jocs-puzle':setupJocsPuzle();go('jocsPuzle');return;
case'jocs-pocio':resetPocio();go('jocsPocio');return;
case'jocs-pocio-mix':pocioMix();return;
case'end-jocs-pocio':notify('QUINA POCIÓ!');remember('jocs-pocio');nav('workshop');return;
case'reset-jocs-pocio':resetPocio();render();return;
case'end-jocs-count':notify('HAS COMPTAT MOLT BÉ!');remember('jocs-count');nav('workshop');return;
case'end-jocs-puzle':notify('PUZZLE FET!');remember('jocs-puzle');nav('workshop');return;
case'reset-jocs-count':setupJocsCount();jocsPuzleSel=null;render();return;
case'reset-jocs-puzle':setupJocsPuzle();jocsPuzleSel=null;render();return;
case'end-jocs-ombres':ombresClearAuto();ombresEnsureSession();ombresSaveSession();if(!ombresActivitatsRuntimeOn()&&f2.ombresSession.levelsCompleted?.includes(3)&&!state.unlocked['jocs-ombres']){notify(strip(ombresMissions().completedTitle||'TRES ESTRELLES!'));remember('jocs-ombres')}nav('tower');return;
case'ombres-begin-search':ombresClearAuto();if(!jocs.ombres.activeSecrets.length)ombresPrepMission('searching');else{jocs.ombres.phase='searching';ombresResetLight()}render();return;
case'ombres-nova-aventura':ombresNovaAventura();render();return;
case'ombres-next-mission':ombresClearAuto();jocs.ombres.starPop=false;ombresAdvanceMission();render();return;
case'ombres-finish-level':ombresClearAuto();jocs.ombres.starPop=false;ombresOnLevelComplete();render();return;
case'ombres-replay-level':ombresStartLevel(ombresPlayingLevel());render();return;
case'ombres-replay-all':ombresNovaAventura();render();return;
case'ombres-replay-session':ombresStartLevel(ombresPlayingLevel());render();return;
case'ombres-play-level-0':ombresStartLevel(0);render();return;
case'ombres-play-level-1':ombresStartLevel(1);render();return;
case'ombres-play-level-2':ombresStartLevel(2);render();return;
case'ombres-play-level-3':ombresStartLevel(3);render();return;
case'reset-jocs-ombres':resetOmbres();render();return;
case'jocs-lupa-ombres':resetOmbres();ensureOmbres(()=>go('jocsOmbres'));return;
case'jocs-lupa-diferencies':ensureDiferencies(()=>{difPrepareFreeSession();resetDiferencies();go('jocsDiferencies')});return;
case'end-jocs-lupa':nav('tower');return;
case'end-jocs-diferencies':difClearAuto();if(jocs.diferencies.context?.returnPlace==='granAventura'){if(typeof granAventuraUiReturnHub==='function'){granAventuraUiReturnHub();return}}if(!difActivitatsRuntimeOn()&&jocs.diferencies.stars>=difRoundsGoal()&&!state.unlocked['jocs-diferencies']){notify(strip(difCfg().completedTitle||'TRES ESTRELLES MÀGIQUES!'));remember('jocs-diferencies')}nav('tower');return;
case'dif-start-round':if(!jocs.diferencies.assetsReady)return;difClearAuto();jocs.diferencies.phase='searching';render();return;
case'dif-next':if(jocs.diferencies.pendingRound)return;difClearAuto();difAdvanceRound();render();return;
case'dif-replay-session':difClearAuto();difPrepareFreeSession();resetDiferencies();render();return;
case'dif-replay':difClearAuto();resetDiferencies();render();return;
}return actionJocs(id)};
const renderJocs=render;
render=function(){renderJocs();jocsBind()};
let ombresRaf=0,ombresPtr=null;
function jocsBind(){app.querySelectorAll('[data-jocs-count]').forEach(el=>el.addEventListener('click',()=>{jocs.count.touched.add(Number(el.dataset.jocsCount));render()}));app.querySelectorAll('[data-jocs-pick]').forEach(el=>el.addEventListener('click',()=>{if(jocs.count.touched.size<jocs.count.goal){notify('PRIMER TOCA TOTS ELS OBJECTES!');return}jocs.count.picked=Number(el.dataset.jocsPick);render()}));app.querySelectorAll('[data-jocs-puz]').forEach(el=>el.addEventListener('click',()=>jocsPuzleTap(Number(el.dataset.jocsPuz))));app.querySelectorAll('[data-pocio-ing]').forEach(el=>el.addEventListener('click',()=>pocioPick(el.dataset.pocioIng)));const wall=app.querySelector('[data-ombres-wall]');if(wall&&!wall.dataset.ombresBound){wall.dataset.ombresBound='1';const ombresWallOk=()=>jocs.ombres.phase==='searching';const flush=()=>{ombresRaf=0;if(ombresPtr){ombresMove(ombresPtr[0],ombresPtr[1]);ombresPtr=null}};const mv=e=>{if(!ombresWallOk())return;if(e.pointerType==='mouse'&&e.buttons===0)return;ombresPtr=[e.clientX,e.clientY];if(!ombresRaf)ombresRaf=requestAnimationFrame(flush)};let tap0=null;const dragOff=()=>wall.classList.remove('ombres-wall--drag');wall.addEventListener('pointerdown',e=>{if(!ombresWallOk())return;tap0=[e.clientX,e.clientY];wall.classList.add('ombres-wall--drag');wall.setPointerCapture(e.pointerId);ombresMove(e.clientX,e.clientY)});wall.addEventListener('pointermove',mv);wall.addEventListener('pointerup',e=>{dragOff();if(!ombresWallOk())return;const t=tap0;tap0=null;if(t&&Math.hypot(e.clientX-t[0],e.clientY-t[1])<14)ombresMove(e.clientX,e.clientY,true)});wall.addEventListener('pointercancel',dragOff);if(ombresWallOk())ombresPaintLight();if(jocs.ombres.starPop)setTimeout(()=>{jocs.ombres.starPop=false;const el=app.querySelector('.ombres-star--pop');if(el)el.classList.remove('ombres-star--pop')},700)}
app.querySelectorAll('[data-dif-panel]').forEach(el=>{if(el.dataset.difBound)return;el.dataset.difBound='1';el.addEventListener('pointerdown',e=>{if(difTryTap(e.clientX,e.clientY,el)){render();if(jocs.diferencies.starPop)setTimeout(()=>{jocs.diferencies.starPop=false;render()},700)}})})}